package com.leetcode.backend.model;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;
@Entity @Table(name="curated_collection_items",uniqueConstraints=@UniqueConstraint(columnNames={"collection_id","problem_id"}),indexes=@Index(name="idx_collection_item_position",columnList="collection_id,position"))public class CuratedCollectionItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@JsonIgnore @ManyToOne(optional=false)@JoinColumn(name="collection_id")private CuratedCollection collection;@ManyToOne(optional=false)@JoinColumn(name="problem_id")private Problem problem;private int position;public Long getId(){return id;}public CuratedCollection getCollection(){return collection;}public void setCollection(CuratedCollection v){collection=v;}public Problem getProblem(){return problem;}public void setProblem(Problem v){problem=v;}public int getPosition(){return position;}public void setPosition(int v){position=v;}}
